import{z as B,x as o,o as A,c as d,q as r,j as l,D as e,d as t,s as i,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"贸易协定与 WTO","description":"","frontmatter":{"title":"贸易协定与 WTO","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/trade-agreements.md","filePath":"econ/trade-agreements.md","lastUpdated":1791063341000}'),p={name:"econ/trade-agreements.md"};function m(D,a,T,g,h,c){const n=o("Mermaid");return A(),d("div",null,[a[2]||(a[2]=r('<h1 id="贸易协定与-wto" tabindex="-1">贸易协定与 WTO <a class="header-anchor" href="#贸易协定与-wto" aria-label="Permalink to &quot;贸易协定与 WTO&quot;">​</a></h1><div class="epigraph"><p>互惠把各国的条款外部性内部化，最惠国防止被绕开的优惠侵蚀；GATT/WTO 是捆住最优关税之手的合约，不是自由贸易的颂词。</p><footer>—— Bagwell and Staiger, An Economic Theory of GATT, AER 1999；对照 Maggi 多边主义</footer></div><p><a href="/econ/tariffs-optimal">上一课</a>给出单边 \\(t^*\\) 与报复困境。本课缺口是：为何以及如何用协定约束关税。全球价值链下一课换生产结构；本课钉 GATT 逻辑：互惠、最惠国（MFN）、约束（bindings）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>大国关税改善本国条款、恶化对方条款，是条款外部性。Bagwell–Staiger：若政府目标是政治加权福利（含游说），有效协定仍应消掉条款外部性，把关税收到政治上的有效点，而不必是社会最优零关税。互惠：你降我的出口壁垒，我降你的，条款大致不变，各自收获效率。MFN：对所有成员同一税率，减少「对 A 优惠、把成本转给 B」的双边操纵。缺口不是联合国年史，而是：协定的经济功能是什么。</p><p><span class="marginnote">术语翻译：「条款外部性」就是一国的关税会改变别国做买卖时的「讨价还价位置」——好比你在菜市场压价，压的是整个市场的行情，别人的进货成本跟着变，但你不必赔他们一分钱。</span></p><p><span class="marginnote">争端解决与授权报复是执行装置，不是法庭浪漫。退出威胁、安全例外、反倾销，都是合约不完全。本课机制优先，条款清单不背。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>条款外部性 → 谈判要互惠。政治经济：Grossman–Helpman 保护出售给出单边政治关税，协定在其上再削条款部分。区域协定（FTA/关税同盟）对多边的绊脚石 / 垫脚石：特惠转移（贸易转移 Viner）可以损世界。WTO 的约束关税（ceiling）允许实际税率低于约束，提供灵活性与可信上限。</p>',9)),(A(),l(s,null,{default:e(()=>[i(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXT%5B%22%E6%9D%A1%E6%AC%BE%E5%A4%96%E9%83%A8%E6%80%A7%22%5D%20--%3E%20REC%5B%22%E4%BA%92%E6%83%A0%E8%B0%88%E5%88%A4%22%5D%0A%20%20MFN%5B%22%E6%9C%80%E6%83%A0%E5%9B%BD%22%5D%20--%3E%20NO%5B%22%E9%98%B2%E6%AD%A2%E7%89%B9%E6%83%A0%E8%BD%AC%E5%AB%81%22%5D%0A%20%20BIND%5B%22%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20CRED%5B%22%E5%8F%AF%E4%BF%A1%E4%B8%8A%E9%99%90%22%5D%0A%20%20PTA%5B%22%E5%8C%BA%E5%9F%9F%E7%89%B9%E6%83%A0%22%5D%20--%3E%20VINER%5B%22%E5%88%9B%E9%80%A0%20vs%20%E8%BD%AC%E7%A7%BB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与引力：FTA 系数是平均相关，不是 Bagwell–Staiger 识别。要因果需设计（加入时点、产品覆盖），仍受多边阻力约束。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是合约。单边最优是占优策略，协定改支付矩阵。互惠使「我降税」不再等于「我条款恶化」。MFN 使让步多边化，减少对局外人抽租。政治加权意味着协定后仍可有正关税（游说），但不应再有以邻为壑的那一层。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：甲乙两国各自对进口征 20% 的最优关税，双方出口都受损。互惠谈判下各降到 10%：甲的出口商在乙国少交税，乙的出口商在甲国少交税，谁都没有相对恶化谁的出口条件——这就是互惠「条款大致不变」的含义，效率却都涨了。")],-1)),(A(),l(s,null,{default:e(()=>[i(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20NOAGG%5B%22%E6%97%A0%E5%8D%8F%E5%AE%9A%3A%20%E5%90%84%E8%AE%BE%E5%8D%95%E8%BE%B9%E6%9C%80%E4%BC%98%E5%85%B3%E7%A8%8E%22%5D%20--%3E%20HURT%5B%22%E5%8F%8C%E6%96%B9%E5%87%BA%E5%8F%A3%E6%9D%A1%E6%AC%BE%E9%83%BD%E8%A2%AB%E6%81%B6%E5%8C%96%22%5D%0A%20%20HURT%20--%3E%20PD%5B%22%E4%BD%8E%E6%95%88%E7%9A%84%E5%AF%B9%E5%B3%99%E5%9D%87%E8%A1%A1%22%5D%0A%20%20AGRE%5B%22%E7%AD%BE%E5%8D%8F%E5%AE%9A%3A%20%E4%BA%92%E6%83%A0%20%2B%20%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20LOW%5B%22%E5%8F%8C%E6%96%B9%E5%85%B3%E7%A8%8E%E4%B8%8B%E8%B0%83%22%5D%0A%20%20LOW%20--%3E%20TERMS%5B%22%E6%9D%A1%E6%AC%BE%E5%A4%96%E9%83%A8%E6%80%A7%E8%A2%AB%E5%86%85%E9%83%A8%E5%8C%96%22%5D%0A%20%20TERMS%20--%3E%20WIN%5B%22%E5%90%84%E8%87%AA%E6%95%88%E7%8E%87%E6%94%B9%E5%96%84%22%5D%0A%20%20CHEAT%5B%22%E4%B8%80%E6%96%B9%E5%81%B7%E5%81%B7%E5%8A%A0%E7%A8%8E%22%5D%20--%3E%20RET%5B%22%E5%8F%A6%E4%B8%80%E6%96%B9%E6%8E%88%E6%9D%83%E6%8A%A5%E5%A4%8D%22%5D%0A%20%20RET%20-.-%3E%7C%22%E5%9B%9E%E5%88%B0%E9%81%B5%E5%AE%88%22%7C%20LOW%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">常见误区：初学者容易以为 WTO 的目标是逼所有国家把关税降到零。实际上协定只是把「以邻为壑」的那部分关税内部化——游说政治下保留一些正关税，也可以是有效协定的组成部分。</span></p><p>与不可能三角、资本账户无关：这是货物壁垒合约。服务、投资、知识产权是后代议题，逻辑类似外部性与互惠，对象不同。</p><p><span class="marginnote">Viner：关税同盟创造贸易（从高成本国内转向成员）也转移贸易（从更低成本的世界转向成员）。净福利不定。区域主义不是自动的多边加速器。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不预测某次部长会议结果。不把 WTO 危机写成已经替代理论。下一课价值链：中间品关税被放大，有效保护与名义税率分叉，协定的产品规则（原产地）变得更关键。China shock 是冲击分配，不是协定理论的否证。不要用「自由贸易协定」字面当成已达零关税有效。</p><p>后课默认：GATT 逻辑是内部化条款外部性；互惠 + MFN + 约束是手段。政治关税可以留下。区域特惠要问创造还是转移。单边 \\(t^*\\) 仍是无协定时的威胁点。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>条款外部性使单边关税过高；互惠内部化。</li><li>MFN 防止特惠把成本转给第三方。</li><li>政治目标下协定有效 ≠ 零关税。</li><li>Viner：区域同盟可转移贸易，世界福利不定。</li><li>出处：Bagwell and Staiger, <em>AER</em> 1999；Grossman and Helpman；Viner。</li></ul>',8))])}const C=B(p,[["render",m]]);export{u as __pageData,C as default};
